package org.sleepwell.app;
import android.app.*;
import android.content.*;
import android.os.*;
import android.view.View;
import androidx.test.platform.app.InstrumentationRegistry;
import androidx.test.runner.lifecycle.*;
import androidx.test.uiautomator.*;
import org.junit.Test;
import java.io.File;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.Assert.*;
/** Owned native settings on an explicit disposable emulator; scheduler and launcher are inert. */
public class RecurringTrackingFlowTest {
    final Instrumentation i=InstrumentationRegistry.getInstrumentation();final Context c=i.getTargetContext();final UiDevice device=UiDevice.getInstance(i);
    UiObject2 object(BySelector selector){UiObject2 found=device.wait(Until.findObject(selector),5000);assertNotNull(selector.toString(),found);return found;}
    void click(String text)throws Exception{UiObject2 found=device.wait(Until.findObject(By.text(text)),2000);if(found==null){UiScrollable scroll=new UiScrollable(new UiSelector().scrollable(true));assertTrue(text,scroll.exists());scroll.scrollIntoView(new UiSelector().text(text));found=device.wait(Until.findObject(By.text(text)),3000);}assertNotNull(text,found);found.click();device.waitForIdle();}
    Activity focused(Activity previous){Activity[] found={null};long until=SystemClock.elapsedRealtime()+5000;while(found[0]==null){i.runOnMainSync(()->{for(Activity a:ActivityLifecycleMonitorRegistry.getInstance().getActivitiesInStage(Stage.RESUMED))if(a instanceof RecurringTrackingActivity&&a!=previous&&a.getWindow().getDecorView().isAttachedToWindow())found[0]=a;});assertTrue("Resumed recurring settings",found[0]!=null||SystemClock.elapsedRealtime()<until);if(found[0]==null)SystemClock.sleep(25);}return found[0];}
    final class Harness implements AutoCloseable {
        final RecurringTracking.Port old=RecurringTracking.port;final RecurringTrackingTest.Fake fake=new RecurringTrackingTest.Fake(c);final Map<String,?> prefs=Prefs.of(c).getAll();final List<Activity> owned=new CopyOnWriteArrayList<>();final Application app=(Application)c.getApplicationContext();final File folder=new File(c.getExternalFilesDir(null),"verification");
        final Application.ActivityLifecycleCallbacks lifecycle=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle b){owned.add(a);assertTrue("No external permissions, tracking or alarm screen allowed",a instanceof RecurringTrackingActivity);}public void onActivityStarted(Activity a){}public void onActivityResumed(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};
        Harness()throws Exception{assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertTrue(Build.HARDWARE.contains("ranchu")||Build.HARDWARE.contains("goldfish"));assertEquals("1",device.executeShellCommand("getprop ro.kernel.qemu").trim());assertFalse(TrackingService.running);assertFalse(AlarmService.active);assertFalse(Prefs.flag(c,"ringing"));assertFalse(Prefs.flag(c,"tracking"));assertTrue(folder.isDirectory()||folder.mkdirs());app.registerActivityLifecycleCallbacks(lifecycle);i.runOnMainSync(()->RecurringTracking.port=fake);}
        void start(){Instrumentation.ActivityMonitor monitor=i.addMonitor(RecurringTrackingActivity.class.getName(),null,false);Activity previous=null;try{c.startActivity(new Intent(c,RecurringTrackingActivity.class).putExtra("visualReview",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Activity created=monitor.waitForActivityWithTimeout(5000);assertNotNull(created);long until=SystemClock.elapsedRealtime()+5000;while(!created.hasWindowFocus()&&SystemClock.elapsedRealtime()<until)SystemClock.sleep(25);assertTrue(created.hasWindowFocus());}finally{i.removeMonitor(monitor);}}
        void recreate(){Activity a=focused(null);i.runOnMainSync(a::recreate);focused(a);}
        void capture(String suffix)throws Exception{Activity a=focused(null);CountDownLatch frame=new CountDownLatch(1);i.runOnMainSync(()->{View decor=a.getWindow().getDecorView();decor.getViewTreeObserver().registerFrameCommitCallback(frame::countDown);decor.invalidate();});assertTrue(frame.await(5,TimeUnit.SECONDS));device.waitForIdle();assertTrue(device.takeScreenshot(new File(folder,"recurring-"+suffix+".png")));}
        void diagnostic(Throwable failure){try{device.takeScreenshot(new File(folder,"recurring-failure.png"));device.dumpWindowHierarchy(new File(folder,"recurring-failure.xml"));}catch(Exception error){failure.addSuppressed(error);}}
        public void close()throws Exception{try{i.runOnMainSync(()->{for(Activity a:owned)if(!a.isDestroyed())a.finish();});long until=SystemClock.elapsedRealtime()+5000;while(owned.stream().anyMatch(a->!a.isDestroyed())&&SystemClock.elapsedRealtime()<until)SystemClock.sleep(25);assertTrue(owned.stream().allMatch(Activity::isDestroyed));assertEquals("No hardware launcher ran",0,fake.launches);assertEquals(prefs,Prefs.of(c).getAll());assertFalse(TrackingService.running);assertFalse(AlarmService.active);}finally{app.unregisterActivityLifecycleCallbacks(lifecycle);i.runOnMainSync(()->RecurringTracking.port=old);assertTrue(fake.p.edit().clear().commit());assertTrue(c.deleteSharedPreferences(fake.name));}}
    }
    @Test public void saveCancelRecreateReopenAndDisablePersistWithoutArmingTonight()throws Exception{try(Harness h=new Harness()){try{h.start();h.capture("off");object(By.desc("Nightly tracking")).click();object(By.desc("After settling")).click();object(By.desc("Only when charging")).click();h.capture("draft");h.recreate();object(By.desc("After settling").selected(true));h.capture("draft-recreated");assertFalse(h.fake.p.getBoolean("enabled",false));click("Cancel");h.start();assertFalse(h.fake.p.getBoolean("enabled",false));object(By.desc("Nightly tracking")).click();object(By.desc("After settling")).click();object(By.desc("Only when charging")).click();click("Start time");object(By.desc("Minute")).setText("15");h.recreate();assertEquals("15",object(By.desc("Minute")).getText());h.capture("time-recreated");click("Use time");click("Save nightly settings");assertTrue(h.fake.p.getBoolean("enabled",false));assertTrue(h.fake.p.getBoolean("stillness",false));assertTrue(h.fake.p.getBoolean("charging",false));assertEquals(15,h.fake.p.getInt("minute",0)%60);assertTrue(h.fake.schedules>0);h.start();object(By.desc("After settling").selected(true));h.capture("saved");h.recreate();h.capture("saved-recreated");object(By.desc("Nightly tracking")).click();click("Save nightly settings");assertFalse(h.fake.p.getBoolean("enabled",true));h.start();h.capture("disabled");assertEquals(0,h.fake.stops);}catch(Throwable failure){h.diagnostic(failure);throw failure;}}}
    @Test public void unavailablePermissionsAndSchedulingFailureRemainVisibleAfterRecreation()throws Exception{try(Harness h=new Harness()){try{h.fake.exact=false;h.start();h.capture("permission");object(By.desc("Nightly tracking")).click();click("Save nightly settings");object(By.text("Allow exact alarms to schedule nightly tracking."));h.capture("permission-error");h.recreate();object(By.text("Allow exact alarms to schedule nightly tracking."));h.capture("permission-recreated");h.fake.exact=true;h.fake.notifications=false;click("Save nightly settings");object(By.text("Allow notifications so the tracking cancel control stays visible."));h.capture("notifications-error");h.fake.notifications=true;h.fake.failSchedule=true;click("Save nightly settings");assertTrue(h.fake.p.getBoolean("enabled",false));assertEquals("",h.fake.p.getString("pending",""));object(By.textStartsWith("Settings were saved, but the next start could not be scheduled."));click("How this works");object(By.text("Nightly tracking"));h.capture("limits");click("Got it");h.capture("schedule-error");assertEquals(0,h.fake.launches);}catch(Throwable failure){h.diagnostic(failure);throw failure;}}}
}
